metrics.sql:
SELECT '${stat_date}' AS stat_date,COUNT(CASE WHEN t.reg_date>='${stat_date}' AND t.reg_date<DATE_ADD('${stat_date}',INTERVAL 1 DAY) THEN t.user_id END) AS metric_value
FROM haoshen_dwd.dwd_user_info_di t
WHERE t.log_date='${stat_date}';

SELECT '${stat_date}' AS stat_date,COALESCE(SUM(t.money+t.bank_money),0) AS metric_value
FROM haoshen_dwd.dwd_user_info_di t LEFT JOIN haoshen_ods.bs_user_id b ON t.user_id=b.user_id
WHERE t.log_date='${stat_date}' AND b.user_id IS NULL;

models.sql:
SELECT fgl_id,log_date,user_id,game_id,room_type_id,num_shot,gold_shot_cost,gold_catch_fish
FROM haoshen_ods.fish_game_log
WHERE log_date >= '${start_date}' AND log_date < '${end_date}';
